UPDATE runtime_operations SET lease_expires_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER)+(?5*1000000),updated_at=CAST(unixepoch('subsec') * 1000000 AS INTEGER) WHERE id=?1 AND attempt=?2 AND lease_token=?3 AND worker_id=?4 AND status IN ('running','delivering') AND lease_expires_at>CAST(unixepoch('subsec') * 1000000 AS INTEGER) RETURNING lease_expires_at,cancel_requested;